    response_format: responseFormat,
    requires_confirmation: pending.requires_confirmation === true,
    pending_actions: pending.pending_actions || null,
    pipeline_passes: [{
      kind: pending.requires_confirmation === true ? 'confirmation_request' : 'initial',
      plan: compactPassPlan(plan),
      action_results: actionResults.map((entry) => ({
        id: entry.id,
        name: entry.name,
        status: entry.status,
        summary: entry.summary,
        error: entry.error
      })),
      response_format: responseFormat
    }],
    interaction: pending.interaction || null,
    workflow_cypher: pending.workflow_cypher || null,
    workflow_validation: responseEntry.workflow_validation || pending.workflow_validation || null,
    workflow_execution_output: workflowExecutionOutput
  },
  __activeOutputs: ['output']
};
